/**
 * Module-level Zag toast store.
 *
 * `@zag-js/toast` v1 is a group store + per-toast child services, not a single
 * machine. The store is plain module state: it is created once when this module
 * is first imported, it never becomes Marko reactive state, and it never crosses
 * a tag-input boundary — so there is nothing here for Marko to serialize.
 *
 * The store is the trigger surface (`toast.success(...)`), the `<Toaster>`
 * component is the render surface, and they are connected by Zag's own
 * subscription rather than by Marko props.
 */
import * as toastMachine from "@zag-js/toast";

export type ToastType = toastMachine.Type;
export type ToastPlacement = toastMachine.Placement;
export type ToastOptions = toastMachine.Options<string>;

/**
 * Options accepted by every `toast.*` helper: the full Zag option set, or a
 * bare string used as the title.
 */
export type ToastArgument = ToastOptions | string;

function toOptions(argument: ToastArgument): ToastOptions {
  return typeof argument === "string" ? { title: argument } : argument;
}

/**
 * The live Zag toast store. Created at module scope so every importer — trigger
 * buttons anywhere in the app and the `<Toaster>` region — shares one instance.
 */
export const toaster = toastMachine.createStore({
  placement: "bottom-end",
  overlap: false,
  gap: 16,
  offsets: "1rem",
  max: 24,
  removeDelay: 200,
  pauseOnPageIdle: true,
});

/**
 * Public toast API. Each helper returns the created toast id where Zag provides
 * one, so callers can `update` or `dismiss` a specific toast later.
 */
export const toast = {
  /** Create a toast with an explicit (or default) type. */
  create: (argument: ToastArgument) => toaster.create(toOptions(argument)),
  /** Create a plain, untyped toast. */
  message: (argument: ToastArgument) => toaster.create(toOptions(argument)),
  /** Create a success toast. */
  success: (argument: ToastArgument) => toaster.create({ ...toOptions(argument), type: "success" }),
  /** Create an error toast. */
  error: (argument: ToastArgument) => toaster.create({ ...toOptions(argument), type: "error" }),
  /** Create an informational toast. */
  info: (argument: ToastArgument) => toaster.create({ ...toOptions(argument), type: "info" }),
  /** Create a warning toast. */
  warning: (argument: ToastArgument) => toaster.create({ ...toOptions(argument), type: "warning" }),
  /** Create a loading toast. Loading toasts never auto-dismiss. */
  loading: (argument: ToastArgument) => toaster.create({ ...toOptions(argument), type: "loading" }),
  /** Update an existing toast in place. */
  update: (id: string, options: Partial<ToastOptions>) => toaster.update(id, options),
  /** Dismiss one toast, or every toast when no id is given. */
  dismiss: (id?: string) => toaster.dismiss(id),
  /** Remove one toast immediately, skipping the exit transition. */
  remove: (id?: string) => toaster.remove(id),
  /** Pause the auto-dismiss timer of one toast, or of every toast. */
  pause: (id?: string) => toaster.pause(id),
  /** Resume the auto-dismiss timer of one toast, or of every toast. */
  resume: (id?: string) => toaster.resume(id),
  /** Drive a toast through a promise's loading/success/error states. */
  promise: <Value>(
    promise: Promise<Value> | (() => Promise<Value>),
    options: toastMachine.PromiseOptions<Value, string>,
    shared?: Omit<ToastOptions, "type">,
  ) => toaster.promise(promise, options, shared),
  /** Whether a toast is currently visible. */
  isVisible: (id: string) => toaster.isVisible(id),
  /** The number of toasts currently held by the store. */
  getCount: () => toaster.getCount(),
};

// One live Zag toast child service, rendered by <Toaster> for each entry in the
// group machine's `toasts` context.
//
// Serialization contract: this component is only ever instantiated on the
// client (the toaster region server-renders empty, because toasts are created
// by user interaction). Its inputs are two closures created in the parent's
// template — `options` and `parent` — plus a number. Template-created closures
// are serializable currency in Marko; the unserializable values they close over
// (the running group service, the Zag option object) never appear as tag input
// themselves.
import * as toastMachine from "@zag-js/toast";
import Icon from "../icon/icon.marko";
import { cn } from "../../../lib/utils.ts";

export interface Input {
  /** Getter for this toast's options as held by the group machine. */
  options: () => toastMachine.Props;
  /** Getter for the running group service that owns this toast. */
  parent: () => toastMachine.GroupService;
  /** This toast's position in the group, front-most first. */
  index: number;
  /**
   * The group service's update counter.
   *
   * Half of this machine's rendered geometry comes from the PARENT's context —
   * `computed("height")`, `heightIndex`, `heightBefore` and `zIndex` all read
   * `prop("parent").context`. A group update therefore has to invalidate this
   * child's connected api, and reading the counter inside `machineProps` is
   * what makes `<service>`'s tracking script call `propsChanged()` here.
   */
  groupRevision: number;
  /**
   * Extra class(es) applied to this toast's root, merged after the built-in
   * ones. Threaded down from `<Toaster>`'s `toastClass` input — the zag-native
   * equivalent of sonner's `toastOptions.classNames.toast`.
   */
  toastClass?: string;
}

<const/machineProps=() => ({
  ...input.options(),
  index: input.index,
  parent: input.parent(),
  groupRevision: input.groupRevision,
})/>
<service/service machine=() => toastMachine.machine props=machineProps/>
<connect/api=(service, normalizeProps) =>
  toastMachine.connect(service, normalizeProps)
  service=service
/>

// The machine measures this toast in a microtask fired by its entry action —
// which in Marko lands before the browser has laid the new element out, so the
// measurement reads 0 and the whole stack collapses onto one offset. Re-send
// the machine's own MEASURE event once layout has actually happened.
<lifecycle
  onMount() {
    const frame = requestAnimationFrame(() => {
      requestAnimationFrame(() => service.service?.send({ type: "MEASURE" }));
    });
    return { cleanup: () => cancelAnimationFrame(frame) };
  }
  onDestroy() {
    this.cleanup?.();
  }
/>

<div
  ...api().getRootProps()
  data-slot="toast"
  class=cn(
    input.toastClass,
    // Zag drives placement/stacking through CSS custom properties on this
    // element (--x/--y/--scale/--z-index/--height/--opacity). They must be
    // consumed by the `translate`/`scale` PROPERTIES, not by Tailwind's
    // `transform` utilities, which would overwrite them.
    "group pointer-events-auto relative flex w-[356px] max-w-[calc(100vw-2rem)] items-start gap-3 rounded-lg border border-border bg-popover p-4 text-sm text-popover-foreground shadow-lg outline-none",
    // `--scale` is only set for background toasts in overlap mode, so it needs
    // an identity fallback. `--height` is deliberately NOT consumed: Zag
    // measures each toast with `offsetHeight`, and binding the CSS `height` to
    // the measurement it feeds produces a 0px fixed point on first paint.
    // `min-h` keeps the stack offsets stable while the content sizes itself.
    "min-h-14 [translate:var(--x)_var(--y)] [scale:var(--scale,1)] [z-index:var(--z-index)] opacity-[var(--opacity)]",
    "[will-change:translate,opacity,scale] [transition:translate_400ms,scale_400ms,opacity_400ms] [transition-timing-function:cubic-bezier(0.21,1.02,0.73,1)]",
    "data-[state=closed]:[transition:translate_400ms,scale_400ms,opacity_200ms]",
    "focus-visible:ring-[3px] focus-visible:ring-ring/50",
    "data-[type=error]:border-destructive/50 data-[type=error]:text-destructive",
  )
>
  // Ghost elements keep hover/pointer state stable across the gap between
  // toasts and during exit transitions. The "before" ghost is scaled to twice
  // the root height, so every real part must stack above it to stay clickable.
  //
  // These must be <div>, not <span>: Zag's getGhostBefore/AfterStyle set
  // block-box geometry (position/inset/height/width), and `normalize.element`
  // types the props as div attributes.
  <div ...api().getGhostBeforeProps()/>

  // Deliberately NOT converted to <Icon>: this is lucide's `circle-check-big`
  // (a broken-arc circle with an oversized check breaking out of it), and the
  // abstract icon-name set <Icon> resolves against is the 191-name mapping
  // vendored verbatim from shadcn's public/r/icons/index.json (see
  // tooling/build-icons.ts) — that set has no `circle-check-big` entry. Its
  // nearest neighbours (CircleCheckIcon / CheckCircle2Icon) are the DIFFERENT
  // `circle-check` glyph (closed circle, small inset check), so swapping would
  // silently change the rendered mark. Left inline until the mapping gains the
  // name.
  <if=(api().type === "success")>
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" data-slot="toast-icon" class="mt-0.5 size-4 shrink-0 relative z-[1] text-emerald-500">
      <path d="M21.801 10A10 10 0 1 1 17 3.335"/>
      <path d="m9 11 3 3L22 4"/>
    </svg>
  </if>
  <else-if=(api().type === "error")>
    <Icon
      name="CircleAlertIcon"
      data-slot="toast-icon"
      class="mt-0.5 size-4 shrink-0 relative z-[1] text-destructive"
    />
  </else-if>
  <else-if=(api().type === "warning")>
    <Icon
      name="TriangleAlertIcon"
      data-slot="toast-icon"
      class="mt-0.5 size-4 shrink-0 relative z-[1] text-amber-500"
    />
  </else-if>
  <else-if=(api().type === "info")>
    <Icon
      name="InfoIcon"
      data-slot="toast-icon"
      class="mt-0.5 size-4 shrink-0 relative z-[1] text-blue-500"
    />
  </else-if>
  <else-if=(api().type === "loading")>
    <Icon
      name="Loader2"
      data-slot="toast-icon"
      class="mt-0.5 size-4 shrink-0 relative z-[1] animate-spin text-muted-foreground"
    />
  </else-if>

  <div class="relative z-[1] flex min-w-0 flex-1 flex-col gap-1">
    <if=api().title>
      <div ...api().getTitleProps() data-slot="toast-title" class="font-medium leading-none">
        ${api().title}
      </div>
    </if>
    <if=api().description>
      <div ...api().getDescriptionProps() data-slot="toast-description" class="text-sm text-muted-foreground">
        ${api().description}
      </div>
    </if>
  </div>

  <if=input.options().action>
    <button
      ...api().getActionTriggerProps()
      data-slot="toast-action"
      class="relative z-[1] inline-flex h-8 shrink-0 items-center rounded-md border border-border bg-transparent px-3 text-xs font-medium transition-colors hover:bg-secondary focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
    >
      ${input.options().action?.label}
    </button>
  </if>

  <if=api().closable>
    <button
      ...api().getCloseTriggerProps()
      data-slot="toast-close"
      aria-label="Dismiss notification"
      class="relative z-[1] shrink-0 rounded-xs text-muted-foreground opacity-70 transition-opacity hover:opacity-100 focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
    >
      <Icon name="X" class="size-4"/>
    </button>
  </if>

  <div ...api().getGhostAfterProps()/>
</div>

// Toaster: the Zag toast *group* region.
//
// Architecture (Zag v1 toast is a group store + per-toast child services):
//
//   store.ts        module-level createStore() — the trigger API, never
//                   reactive state, never tag input, so never serialized.
//   <Toaster>       one group <service>/<connect> whose only machine prop is
//                   { id, store }. The store reaches it through a template
//                   closure (`groupProps`), not through tag input.
//   <toast-item>    one child <service> per visible toast, spawned by <for>.
//                   Marko gives each <for> iteration its own component
//                   instance and therefore its own <lifecycle>, which is
//                   exactly the per-toast machine lifetime Zag wants.
//
// SSR renders the region with zero toasts (toasts are user-triggered), so no
// toast-item and no Zag service ever exists on the server. Hydration resumes an
// empty region; the group service starts on mount and subscribes to the store.
import * as toastMachine from "@zag-js/toast";
import { toaster } from "./store.ts";
import { cn } from "../../../lib/utils.ts";
import ToastItem from "./toast-item.marko";

export interface Input extends Marko.Input<"div"> {
  /** Accessible label for the notification region. @default "Notifications" */
  label?: string;
  /**
   * Text direction passed to the group machine.
   *
   * Typed as the full HTML `dir` surface, not just `"ltr" | "rtl"`: this Input
   * extends `Marko.Input<"div">`, and re-declaring `dir` more narrowly than
   * the attribute it inherits makes every `...rest` spread from a div-shaped
   * parent (e.g. `sonner.marko`) a type error. `"auto"` and the absent values
   * are normalized away below, since Zag's group machine accepts only the two
   * concrete directions.
   */
  dir?: Marko.Input<"div">["dir"];
  /**
   * Extra class(es) applied to every toast's root element. The zag-native
   * equivalent of sonner's `toastOptions.classNames.toast`. `sonner.marko`
   * passes the `mu-toast` style hook through here, mirroring upstream
   * `sonner.tsx`'s `toastOptions={{ classNames: { toast: "cn-toast" } }}`.
   */
  toastClass?: string;
}

<const/{ class: className, label, dir, toastClass, ...rest }=input/>

<id/regionId/>
// Zag's group machine takes `"ltr" | "rtl"` only, so `"auto"` (and the absent
// values HTML allows) fall back to undefined and let the machine default.
<const/machineDir=(dir === "ltr" || dir === "rtl" ? dir : undefined)/>
<const/groupProps=() => ({ id: regionId, store: toaster, dir: machineDir })/>
<service/service machine=() => toastMachine.group.machine props=groupProps/>
<connect/api=(service, normalizeProps) =>
  toastMachine.group.connect(service, normalizeProps)
  service=service
/>

// The group service must be handed to each child machine as `parent`. It is
// passed as a GETTER closure created here in the template: the closure is
// serializable, the running service it returns never is tag input itself.
//
// `service.service` is null only during SSR, and SSR renders zero toasts (the
// <for> below iterates an empty list), so no <toast-item> can ever call this
// getter while it is null. Assert that invariant rather than widening the
// child's `parent` input to allow null, which the Zag machine does not accept.
<const/getParentService=() => {
  const groupService = service.service;
  if (!groupService) {
    throw new Error(
      "[toast] group service is not running — <toast-item> was rendered before <Toaster> mounted.",
    );
  }
  return groupService;
}/>

<div
  ...rest
  ...api().getGroupProps({ label })
  data-slot="toaster"
  class=cn("outline-none", className)
>
  // `ToastProps["id"]` is optional only as *creation input*: the store assigns
  // `data.id ?? uuid()` before a toast is ever stored, so every entry returned
  // by getToasts() carries a real id. The fallback keeps the key a string
  // without inventing a value that could collide with a caller-supplied id.
  <for|toastOptions, index| of=api().getToasts() by=(item, index) => item.id ?? `toast:index:${index}`>
    <ToastItem
      options=() => toastOptions
      parent=getParentService
      index=index
      groupRevision=service.rev
      toastClass=toastClass
    />
  </for>
</div>
